-- Uusi geometria-aineiston ajastus, mutta entuudestaan tuttu aineisto: päällystyskohteiden validoinnissa käytetty kaista-aineisto.
INSERT INTO geometriapaivitys(nimi, paikallinen, kaytossa, lisatieto) VALUES ('laajennettu-tieverkko', true, true, 'Kaista-aineiston tietokantaan luku. Harja lukee kaista-aineiston vain paikallisesta sijainnista. Tiedon hakee rajapinnasta lambda.'
